func testEquipamentoToManyAddOpEquEquipamentoProcessoEqus(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Equipamento
	var b, c, d, e EquipamentoProcessoEqu

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, equipamentoDBTypes, false, strmangle.SetComplement(equipamentoPrimaryKeyColumns, equipamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*EquipamentoProcessoEqu{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, equipamentoProcessoEquDBTypes, false, strmangle.SetComplement(equipamentoProcessoEquPrimaryKeyColumns, equipamentoProcessoEquColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*EquipamentoProcessoEqu{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddEquEquipamentoProcessoEqus(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.EquID != first.EquID {
			t.Error("foreign key was wrong value", a.EquID, first.EquID)
		}
		if a.EquID != second.EquID {
			t.Error("foreign key was wrong value", a.EquID, second.EquID)
		}

		if first.R.Equ != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Equ != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.EquEquipamentoProcessoEqus[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.EquEquipamentoProcessoEqus[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.EquEquipamentoProcessoEqus().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
func testEquipamentoToOneCentroDeCustoUsingCDC(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Equipamento
	var foreign CentroDeCusto

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, equipamentoDBTypes, true, equipamentoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Equipamento struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, centroDeCustoDBTypes, false, centroDeCustoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize CentroDeCusto struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.CDCID, foreign.CDCID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.CDC().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.CDCID, foreign.CDCID) {
		t.Errorf("want: %v, got %v", foreign.CDCID, check.CDCID)
	}

	ranAfterSelectHook := false
	AddCentroDeCustoHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *CentroDeCusto) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := EquipamentoSlice{&local}
	if err = local.L.LoadCDC(ctx, tx, false, (*[]*Equipamento)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CDC == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.CDC = nil
	if err = local.L.LoadCDC(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CDC == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

