func testEquipamentoToOneSetOpCentroDeCustoUsingCDC(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Equipamento
	var b, c CentroDeCusto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, equipamentoDBTypes, false, strmangle.SetComplement(equipamentoPrimaryKeyColumns, equipamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, centroDeCustoDBTypes, false, strmangle.SetComplement(centroDeCustoPrimaryKeyColumns, centroDeCustoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, centroDeCustoDBTypes, false, strmangle.SetComplement(centroDeCustoPrimaryKeyColumns, centroDeCustoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*CentroDeCusto{&b, &c} {
		err = a.SetCDC(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.CDC != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.CDCEquipamentos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.CDCID, x.CDCID) {
			t.Error("foreign key was wrong value", a.CDCID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.CDCID))
		reflect.Indirect(reflect.ValueOf(&a.CDCID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.CDCID, x.CDCID) {
			t.Error("foreign key was wrong value", a.CDCID, x.CDCID)
		}
	}
}

